// Webhook output has the request body under $json.body.
// Flatten the envelope and its payload into one item.
const b = $input.first().json.body || {};
if (!b.runId) throw new Error('Missing runId in the request body');
return [{
  json: {
    runId: b.runId,
    ownerId: b.ownerId ?? null,
    jobId: b.jobId ?? null,
    agentId: b.agentId ?? null,
    ...(b.payload || {}),
  },
}];

