// Paper III.i: hold under 30% or over 300% of the median; under 5 prices = unverified
const bid = $('Load bid').first().json;
if (!bid.id) throw new Error('Bid not found');
const p = $input.all()
  .map((i) => Number(i.json.price))
  .filter((x) => Number.isFinite(x) && x > 0)
  .sort((a, b) => a - b);
const n = p.length;
const price = Number(bid.price);
const median = n ? (n % 2 ? p[(n - 1) / 2] : (p[n / 2 - 1] + p[n / 2]) / 2) : null;
let result = 'cleared';
let reason = null;
if (n < 5) {
  result = 'unverified';
  reason = `Only ${n} comparable prices, so this bid is not checked`;
} else if (price < 0.3 * median || price > 3 * median) {
  result = 'held';
  reason = `Similar ${bid.category} jobs went for about USD ${median.toFixed(0)}; `
    + `this bid is USD ${price} (${Math.round((price / median) * 100)}% of that)`;
}
return [{ json: { bidId: bid.id, jobId: bid.job_id, price, result, reason, median, n } }];

const env = $('Read envelope').first().json;
const r = $('Apply rule').first().json;
const message = r.result === 'held'
  ? `Held bid for price review: ${r.reason}`
  : r.result === 'unverified'
    ? `Price not verified: ${r.reason}`
    : `Price OK: USD ${r.price} vs median USD ${r.median?.toFixed(0)} (${r.n} prices)`;
return [{ json: {
  runId: env.runId, ownerId: env.ownerId, agentId: env.agentId, jobId: r.jobId,
  actorLabel: 'Price check', message,
  severity: r.result === 'held' ? 'hold' : 'info',
  data: { bidId: r.bidId, result: r.result, median: r.median, n: r.n },
  notify: { runId: env.runId, role: 'price_check', ok: true, jobId: r.jobId,
            result: { bidId: r.bidId, priceCheck: r.result }, error: null },
} }];
